import{_ as r,C as t,o as n,c as i,a2 as a,E as o}from"./chunks/framework.Dkj3JE0_.js";const _=JSON.parse('{"title":"Base d’apprentissage","description":"","frontmatter":{"title":"Base d’apprentissage"},"headers":[],"relativePath":"fr/blogs/0-start.md","filePath":"fr/blogs/0-start.md"}'),l={name:"fr/blogs/0-start.md"};function c(d,e,u,p,m,g){const s=t("NoteIndex");return n(),i("div",null,[e[0]||(e[0]=a('<h1 id="base-d-apprentissage" tabindex="-1">Base d’apprentissage <a class="header-anchor" href="#base-d-apprentissage" aria-label="Permalink to &quot;Base d’apprentissage&quot;">​</a></h1><p>Voici ma bibliothèque de travail pour les concepts que je veux comprendre, retenir et appliquer. Elle réunit des plans d’étude structurés, des notes thématiques, des exemples résolus, des explications visuelles et des exercices de mise en œuvre.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Ce sont des notes d’étude en évolution, pas une référence définitive. Je les révise à mesure que ma compréhension progresse ; quand la précision compte, référez-vous au programme officiel ou à la documentation de première main.</p></div><h2 id="par-ou-commencer" tabindex="-1">Par où commencer <a class="header-anchor" href="#par-ou-commencer" aria-label="Permalink to &quot;Par où commencer&quot;">​</a></h2><p>Choisissez un parcours selon ce dont vous avez besoin aujourd’hui.</p><div class="learning-directory"><a class="directory-card directory-card--primary" href="/fr/blogs/CFA/plan"><span class="directory-card__number">01 · CFA NIVEAU II</span><strong>Commencer les notes CFA</strong><span class="directory-card__description">Lisez d’abord le plan d’étude, puis suivez « Page suivante » en bas de chaque page, dans l’ordre du programme.</span><span class="directory-card__action">Ouvrir le plan <b>→</b></span></a><a class="directory-card" href="/fr/blogs/JLPT-N2/plan"><span class="directory-card__number">02 · JLPT N2</span><strong>Plan d’apprentissage du japonais</strong><span class="directory-card__description">Lecture, écoute, grammaire et vocabulaire pratiqués en contexte.</span><span class="directory-card__action">Voir le plan <b>↗</b></span></a><a class="directory-card" href="/fr/blogs/German/plan"><span class="directory-card__number">03 · ALLEMAND DES AFFAIRES</span><strong>Plan d’apprentissage de l’allemand</strong><span class="directory-card__description">Une communication pratique pour les réunions, les présentations et l’écrit professionnel.</span><span class="directory-card__action">Voir le plan <b>↗</b></span></a></div><h2 id="cfa-level-ii-directory" tabindex="-1">Sommaire du CFA niveau II <a class="header-anchor" href="#cfa-level-ii-directory" aria-label="Permalink to &quot;Sommaire du CFA niveau II {#cfa-level-ii-directory}&quot;">​</a></h2><p>Les thèmes suivent l’ordre du programme. Chaque note renvoie au module précédent et au suivant, pour lire d’une traite ou entrer directement ci-dessous. Les notes sont traduites des originaux anglais ; en cas d’écart, la version anglaise fait foi.</p>',8)),o(s),e[1]||(e[1]=a('<h2 id="travaux-appliques" tabindex="-1">Travaux appliqués <a class="header-anchor" href="#travaux-appliques" aria-label="Permalink to &quot;Travaux appliqués&quot;">​</a></h2><ul><li><a href="/fr/projects/NCCP.html">Projets</a> — travaux de recherche et de mise en œuvre liés aux thèmes de ce carnet.</li></ul><h2 id="comment-j-utilise-ces-notes" tabindex="-1">Comment j’utilise ces notes <a class="header-anchor" href="#comment-j-utilise-ces-notes" aria-label="Permalink to &quot;Comment j’utilise ces notes&quot;">​</a></h2><ol><li><strong>Planifier :</strong> choisir le résultat de la semaine dans le plan d’apprentissage concerné.</li><li><strong>Apprendre :</strong> lire un module et en reformuler l’idée principale sans regarder.</li><li><strong>Appliquer :</strong> faire des calculs, des questions, du code ou une courte tâche concrète.</li><li><strong>Diagnostiquer :</strong> noter pourquoi une mauvaise réponse ou une implémentation ratée semblait raisonnable.</li><li><strong>Réviser :</strong> revenir sur les points difficiles après deux jours, une semaine et trois semaines.</li></ol><p>Le but n’est pas d’accumuler des pages. Une note est utile quand elle m’aide à retrouver un concept, à prendre une décision ou à résoudre un problème.</p><h2 id="conventions-des-notes" tabindex="-1">Conventions des notes <a class="header-anchor" href="#conventions-des-notes" aria-label="Permalink to &quot;Conventions des notes&quot;">​</a></h2><ul><li>Les encadrés <strong>Important</strong> signalent les distinctions faciles à confondre.</li><li>Les sections <strong>Exam focus</strong> mettent en avant la matière évaluable du CFA.</li><li>Les sections <strong>For understanding</strong> expliquent l’intuition au-delà du programme.</li><li>Les exemples résolus montrent la structure du calcul avant d’interpréter le résultat.</li><li>Les graphiques interactifs et les exemples de code sont des outils d’appui ; la conclusion écrite reste l’essentiel.</li></ul><p>Utilisez la barre latérale pour parcourir l’archive complète, ou revenez ici chaque fois que vous devez choisir la prochaine direction d’étude.</p>',8))])}const v=r(l,[["render",c]]);export{_ as __pageData,v as default};
